"use client";

import React, { useState } from "react";
import * as LucideIcons from "lucide-react";

// Safe icon renderer
function Icon({ name, className }: { name: string, className?: string }) {
    const LucideIcon = (LucideIcons as any)[name];
    if (!LucideIcon) return <div className={className} style={{ width: '20px', height: '20px', backgroundColor: '#333', borderRadius: '4px' }} />;
    return <LucideIcon className={className} />;
}

export default function AdminFinanceiro() {
    const [stats] = useState([
        { label: "RECEITAS", value: "R$ 185", period: "Hoje", icon: "TrendingUp", color: "text-emerald-500" },
        { label: "DESPESAS", value: "R$ 212", period: "Hoje", icon: "TrendingDown", color: "text-red-500" },
        { label: "SALDO", value: "R$ 15.420", period: "Mês", icon: "DollarSign", color: "text-[#D4AF37]" },
    ]);

    const transactions = [
        { id: 1, label: "Corte + Barba — João Santos", time: "09:40", value: "+R$ 65,00", type: "income" },
        { id: 2, label: "Corte Degradê — Pedro Lima", time: "10:35", value: "+R$ 45,00", type: "income" },
        { id: 3, label: "Produtos de limpeza", time: "11:00", value: "-R$ 120,00", type: "expense" },
        { id: 4, label: "Barba — Lucas Oliveira", time: "11:15", value: "+R$ 35,00", type: "income" },
        { id: 5, label: "Corte Social — Marcos Costa", time: "12:00", value: "+R$ 40,00", type: "income" },
    ];

    return (
        <div className="min-h-screen bg-[#0a0a0a] text-white p-6 lg:p-12 font-sans selection:bg-[#D4AF37] selection:text-black animate-fade-in-up">
            <div className="max-w-4xl mx-auto bg-[#111111] border border-[#1f1f1f] rounded-3xl p-8 shadow-2xl h-[calc(100vh-100px)] flex flex-col">
                <header className="flex justify-between items-center mb-10">
                    <div className="flex items-center gap-3">
                        <Icon name="DollarSign" className="w-6 h-6 text-[#D4AF37]" />
                        <h2 className="text-2xl font-bold tracking-tight">Financeiro</h2>
                    </div>
                </header>

                <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-12">
                    {stats.map((stat, i) => (
                        <div key={i} className="bg-[#1a1a1a] border border-[#222] p-6 rounded-2xl">
                            <div className="flex justify-between items-start mb-6">
                                <span className={`text-[#D4AF37] font-bold text-[10px] uppercase tracking-widest flex items-center gap-2`}>
                                    <Icon name={stat.icon} className={`w-3 h-3 ${stat.color}`} /> {stat.label}
                                </span>
                            </div>
                            <h3 className="text-3xl font-bold text-white mb-1 tracking-tight">{stat.value}</h3>
                            <p className="text-gray-500 text-[10px] uppercase font-bold tracking-widest">{stat.period}</p>
                        </div>
                    ))}
                </div>

                <h3 className="text-lg font-bold mb-8 tracking-tight">Movimentações de Hoje</h3>

                <div className="flex-1 overflow-y-auto pr-2 space-y-4 custom-scrollbar">
                    {transactions.map((t) => (
                        <div key={t.id} className="bg-[#1a1a1a] border border-[#222] p-5 rounded-2xl flex items-center justify-between group">
                            <div className="flex items-center gap-6">
                                <div className={`w-12 h-12 rounded-2xl flex items-center justify-center border border-[#222] ${t.type === 'income' ? 'bg-emerald-500/5 text-emerald-500' : 'bg-red-500/5 text-red-500'
                                    }`}>
                                    <Icon name={t.type === 'income' ? 'ArrowUpRight' : 'ArrowDownRight'} className="w-5 h-5" />
                                </div>
                                <div>
                                    <h4 className="font-bold text-base text-gray-200 mb-1">{t.label}</h4>
                                    <p className="text-[10px] text-gray-500 font-bold uppercase tracking-widest">{t.time}</p>
                                </div>
                            </div>
                            <span className={`text-base font-bold tracking-tight ${t.type === 'income' ? 'text-emerald-500' : 'text-red-500'
                                }`}>
                                {t.value}
                            </span>
                        </div>
                    ))}
                </div>
            </div>
        </div>
    );
}
